-- SANKALPA PURE VEG - COMPACT EXCLUSIVE MENU SEED (TiDB-SAFE)
USE smprowor_RMS;

-- OUTLET 1: CATEGORIES
INSERT INTO category (restaurant_id, category_name, description, status)
SELECT c.restaurant_id, c.category_name, c.description, c.status FROM (
SELECT 1 AS restaurant_id, 'Special Dishes' AS category_name, 'Sankalpa Pure Veg chef special curries' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Kaju Special' AS category_name, 'Rich cashew nut gravies and specials' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Mushroom Special' AS category_name, 'Fresh mushroom curries and masala dishes' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Paneer Special' AS category_name, 'Signature cottage cheese gravies and tikkas' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Punjabi Dishes' AS category_name, 'Traditional Punjabi and Maharashtrian sabzis' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Chinese' AS category_name, 'Indo-Chinese starters and noodles' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Sweet Bhaji' AS category_name, 'Mildly spiced creamy and sweet curries' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Aalu Special' AS category_name, 'Classic potato gravies and dum aalu' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Dal Special' AS category_name, 'Homestyle and restaurant-style lentils' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Handi' AS category_name, 'Full and half handi clay-pot specials' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Snacks' AS category_name, 'Hot crispy snacks and quick bites' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Soup' AS category_name, 'Freshly prepared hot soups' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Rice' AS category_name, 'Steamed rice, jeera rice, biryani and fried rice' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Roti' AS category_name, 'Fresh tandoori rotis, naans and parathas' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Papad' AS category_name, 'Roasted, fried and masala papad' AS description, 'ACTIVE' AS status
UNION ALL SELECT 1 AS restaurant_id, 'Cold Drinks' AS category_name, 'Soft drinks, lassi, tak and mineral water' AS description, 'ACTIVE' AS status
) c LEFT JOIN category ex ON ex.restaurant_id = c.restaurant_id AND ex.category_name = c.category_name
WHERE ex.category_id IS NULL;

