-- OUTLET 1: INSERT ALL 171 MENU ITEMS
INSERT INTO menu (restaurant_id, category_id, item_name, description, price, image, status)
SELECT v.restaurant_id, c.category_id, v.item_name, v.description, v.price, v.image, 'AVAILABLE' FROM (
SELECT 1 AS restaurant_id, 'Special Dishes' AS cat_name, 'Veg Tawa' AS item_name, 'Mixed vegetables tossed on hot tawa with spices' AS description, 150.00 AS price, 'images/menu/Veg_Tawa.jpg' AS image
UNION ALL SELECT 1 AS restaurant_id, 'Special Dishes' AS cat_name, 'Veg Kadhai' AS item_name, 'Seasonal veggies cooked in aromatic kadhai masala' AS description, 140.00 AS price, 'images/menu/Veg_Kadhai.jpg' AS image
