) v JOIN category c ON c.restaurant_id = v.restaurant_id AND c.category_name = v.cat_name
LEFT JOIN menu m ON m.restaurant_id = v.restaurant_id AND m.item_name = v.item_name
WHERE m.item_id IS NULL;

DELETE FROM category WHERE restaurant_id IN (1, 2, 3) AND category_name NOT IN ('Special Dishes', 'Kaju Special', 'Mushroom Special', 'Paneer Special', 'Punjabi Dishes', 'Chinese', 'Sweet Bhaji', 'Aalu Special', 'Dal Special', 'Handi', 'Snacks', 'Soup', 'Rice', 'Roti', 'Papad', 'Cold Drinks');
